package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
final class FieldConfirmationPhase2BContractTest {
 private static final Path ROOT=Path.of("..").toAbsolutePath().normalize();
 private static String read(String p)throws Exception{return Files.readString(ROOT.resolve(p)).replace("\r\n","\n");}
 @Test void policyIdentityIsTenantTypeOverlayStableAndAvailableToEveryType()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("CaseDateTypePolicyKey")),()->assertTrue(s.contains("SYSTEM:")),()->assertTrue(s.contains("TYPE:")),()->assertFalse(s.contains("CaseDateSemanticRoleResolver")),()->assertFalse(s.contains("FormConfiguredFields")),()->assertFalse(s.contains("CaseTeam")));}
 @Test void policyIsVersionedConcurrentRoleValidatedTenantAdminAndAudited()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("SupersededAt=SYSUTCDATETIME()")),()->assertTrue(s.contains("expectedPolicyRowVer")),()->assertTrue(s.contains("is_admin=1")),()->assertTrue(s.contains("requireActiveRole")),()->assertTrue(s.contains("FIELD_CONFIRMATION_POLICY")));}
 @Test void everyBusinessWriteAndRestoreEvaluatesButPresentationAndDeletionDoNot()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/CaseDateDao.java");assertAll(()->assertTrue(count(s,"evaluateCaseDate(")>=5),()->assertTrue(s.contains("before.typeId!=c.caseDateTypeId()")),()->assertTrue(s.contains("if(businessChanged)fieldConfirmationDao.evaluateCaseDate")),()->assertTrue(s.contains("if(restore)fieldConfirmationDao.evaluateCaseDate")));}
 @Test void eligibilityAutoConfirmsAndManualConfirmationRemainsTransactional()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("if(hasRole(con,tenant,actor,p.roleId))")),()->assertTrue(s.contains("UserFirmWideRoleAssignments")),()->assertTrue(s.contains("cd.IsDeleted=0")),()->assertTrue(s.contains("SAVED_VALUE_CONFIRMATION")),()->assertTrue(s.contains("con.rollback()")));}
 @Test void migrationFailsClosedOnEnabledLegacyPolicyAndVerificationIsReadOnly()throws Exception{String m=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d.sql"),v=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d_verify.sql");assertAll(()->assertTrue(m.contains("Enabled New Intake field confirmation policies exist")),()->assertTrue(m.contains("CaseDateTypePolicyKey")),()->assertFalse(v.contains("REPLACE_WITH")),()->assertFalse(v.matches("(?is).*(INSERT|UPDATE|DELETE|MERGE|ALTER|CREATE|DROP)\\s+dbo\\..*")),()->assertTrue(v.contains("explicit rollout decision")));}
 private static int count(String s,String n){int c=0,p=0;while((p=s.indexOf(n,p))>=0){c++;p+=n.length();}return c;}
}
